text(await tools.exec_command({cmd:"cat > apps/simulator-macos/Sources/MarvinSimulator/TownWorld.swift <<'EOF'
import AppKit
import SceneKit
import SimulationCore
import simd

/// A compact, deterministic desert port. Static geometry is baked into spatial
/// cells with two detail levels; the race never acquires scenery physics bodies.
final class TownWorld {
    let root = SCNNode()
    private let surface = SCNMaterial()
    private var cells: [String: TownCell] = [:]
    private var people: [TownPerson] = []
    private(set) var buildings = 0
    private(set) var population = 0
    private(set) var triangleCount = 0
    private(set) var coarseTriangles = 0
    private(set) var animatedCount = 0
    private(set) var lots: [TownLot] = []
    private var clock = 0.0
    private var visibilityClock = -1.0
    private let sand: UInt32 = 0xc5a174, cream: UInt32 = 0xe6c89c
    private let rust: UInt32 = 0xa25a40, teal: UInt32 = 0x427c80
    private let dark: UInt32 = 0x3e4545, trim: UInt32 = 0x9d805e
    private let finishZ = DirtCourse.point(0).z

    struct TownLot {
        let x: Double, z: Double, width: Double, depth: Double
    }
    private final class TownCell {
        let near = TownMesh(), far = TownMesh()
        let origin: SIMD3<Float>
        init(_ x: Float, _ z: Float) { origin = SIMD3(x, 0, z) }
    }
    private struct TownPerson {
        let node: SCNNode, arm: SCNNode, origin: SCNVector3
        let phase: Double, walking: Bool
    }

    init() {
        root.name = "Mos Aster desert spaceport"
        surface.lightingModel = .physicallyBased
        surface.diffuse.contents = plasterTexture()
        surface.roughness.contents = 0.93
        surface.isDoubleSided = false
        buildRoads()
        buildGrandstand()
        buildSettlement()
        buildLandmarks()
        buildStreetLife()
        for key in cells.keys.sorted() {
            let cell = cells[key]!
            let near = cell.near.geometry(material: surface, relativeTo: cell.origin)
            let far = cell.far.geometry(material: surface, relativeTo: cell.origin)
            near.levelsOfDetail = [SCNLevelOfDetail(geometry: far, worldSpaceDistance: 38)]
            let node = SCNNode(geometry: near)
            node.simdPosition = cell.origin; node.name = "Town cell \(key)"
            // Keep expensive shadow submissions bounded. Architecture gets
            // vertex-toned recesses; the sun still gives near walls contact.
            node.castsShadow = abs(cell.origin.x) < 24 && abs(cell.origin.z) < 24
            root.addChildNode(node)
            triangleCount += cell.near.indices.count / 3
            coarseTriangles += cell.far.indices.count / 3
        }
    }

    private func cell(_ x: Double, _ z: Double) -> TownCell {
        let ix = Int(floor(x / 10)), iz = Int(floor(z / 10)), key = "\(ix),\(iz)"
        if let existing = cells[key] { return existing }
        let value = TownCell(Float(ix * 10 + 5), Float(iz * 10 + 5))
        cells[key] = value; return value
    }
    private func paint(_ x: Double, _ z: Double, yaw: Double = 0) -> TownPainter {
        let c = cell(x,z)
        return TownPainter(near: c.near, far: c.far, origin: SIMD3(Float(x),0,Float(z)), yaw: Float(yaw))
    }
    /// Entire footprint plus a margin must clear every part of the spline.
    /// Dense edge/interior samples also prevent a lot spanning another branch.
    private func clearLot(_ x: Double, _ z: Double, _ w: Double, _ d: Double) -> Bool {
        let nx = Int(ceil(w / 0.35)), nz = Int(ceil(d / 0.35))
        for i in 0...nx { for j in 0...nz {
            let px = x-w/2+w*Double(i)/Double(nx), pz = z-d/2+d*Double(j)/Double(nz)
            if DirtCourse.projection(x:px,z:pz).distance < DirtCourse.terrainEdge+0.6 { return false }
        }}
        return true
    }

    private func buildRoads() {
        // Connected outer access streets with narrow pale curbs; streets stay
        // outside the race envelope. Lots reserve these same corridors.
        for x in [-24.0, 24.0] {
            for z in stride(from:-30.0, through:30.0, by:6) {
                let p = paint(x,z)
                p.box(0,0.007,0,2.6,0.025,6.02,0x967957)
                for side in [-1.0,1] { p.box(side*1.4,0.055,0,0.18,0.11,6.02,cream) }
                for offset in [-1.5,1.5] { p.box(0,0.026,offset,0.07,0.01,0.65,0xcbb38c,detail:true) }
            }
        }
        for z in [-25.0,25.0] {
            for x in stride(from:-21.0, through:21.0, by:6) {
                let p = paint(x,z)
                p.box(0,0.008,0,6.02,0.025,2.6,0x967957)
                for side in [-1.0,1] { p.box(0,0.055,side*1.4,6.02,0.11,0.18,cream) }
            }
        }
        // Plaza paving and a route behind the civic arcade.
        let p = paint(0,finishZ-5)
        p.box(0,0.009,-1,16,0.025,5.6,0xbca27c)
        for x in stride(from:-8.0,through:8.0,by:0.8) {
            p.box(x,0.025,-1,0.018,0.008,5.6,trim,detail:true)
        }
    }

    private func buildGrandstand() {
        let z = finishZ-4.4, p = paint(0,z)
        // Shops form the plinth, with seating rising toward the back of town.
        p.box(0,0.67,-0.65,12.8,1.34,3.8,sand)
        p.box(0,0.12,0.9,13.2,0.24,1.0,cream)
        for x in stride(from:-5.5,through:5.5,by:1.85) {
            p.box(x,0.76,1.26,1.42,1.12,0.04,dark)
            p.dome(x,1.28,1.28,0.71,0.45,0.09,sand,detail:true)
            p.box(x,0.16,1.35,1.48,0.18,0.32,trim)
            p.box(x,1.23,1.60,1.55,0.10,0.85,Int(x*10)%2 == 0 ? teal : rust)
            for sx in [-0.72,0.72] { p.box(x+sx,0.62,1.90,0.055,1.24,0.055,dark,detail:true) }
            for k in 0..<3 { p.box(x-0.42+Double(k)*0.38,0.42,1.44,0.28,0.35,0.23,0xa17c51,detail:true) }
        }
        for row in 0..<5 {
            let y=1.4+Double(row)*0.31, rz=0.72-Double(row)*0.56
            p.box(0,y-0.12,rz,12.6,0.24,0.58,cream)
            p.box(0,y+0.06,rz-0.12,12.1,0.12,0.25,rust,detail:true)
            for seat in 0..<22 where seat != 10 && seat != 11 && (seat+row*3)%9 != 0 {
                let x = -5.7+Double(seat)*0.54
                citizen(x,z+rz,y:y+0.12,yaw:0,index:row*22+seat,seated:true,animated:row == 0 && seat%4 == 0)
            }
        }
        // Central aisle and accessible-looking side stairs, not a solid slab.
        for side in [-1.0,1] {
            for step in 0..<12 {
                let h=Double(step+1)*0.225
                p.box(side*6.95,h/2,1.1-Double(step)*0.30,0.85,h,0.31,cream)
            }
            p.box(side*6.45,2.05,-0.4,0.09,1.45,3.65,trim)
        }
        // Shade roof with a gap over the central aisle. Opaque geometry avoids
        // layers of alpha over the crowded start and finish.
        for x in [-3.45,3.45] {
            p.box(x,3.78,-1.12,5.65,0.085,2.8,teal)
            for pole in [-2.7,2.7] { p.box(x+pole,2.49,-2.30,0.07,2.6,0.07,dark,detail:true) }
            for stripe in stride(from:-2.4,through:2.4,by:0.6) {
                p.box(x+stripe,3.826,-1.12,0.10,0.01,2.75,cream,detail:true)
            }
        }
        // Two plaster towers bookend the stand and make the civic landmark
        // readable from the track as well as the opening overview.
        for x in [-8.5,8.5] {
            building(x,finishZ-5.5,w:2.4,d:3.6,h:3.5,index:x < 0 ? 3 : 6,record:false)
            let q=paint(x,finishZ-5.5)
            q.cylinder(0,4.45,0,0.85,0.62,1.8,cream)
            q.dome(0,5.35,0,0.72,0.55,0.72,sand)
            q.box(0,4.55,0.69,0.65,0.5,0.035,dark,detail:true)
            q.box(0,6.1,0,0.055,0.85,0.055,dark,detail:true)
        }
        sign("MOS ASTER", at:SCNVector3(-2.4,1.00,z+1.315),size:0.38,ink:0xeadbbd)
        sign("GRAND PRIX", at:SCNVector3(-1.65,0.60,z+1.32),size:0.22,ink:0xc5a174)
    }

    private func buildSettlement() {
        var index=0
        // Authored street grid with deterministic variation, not runtime random
        // placement. Reserve an entire block for the occupied finish arcade.
        for z in stride(from:-32.0,through:32.0,by:5.5) {
            for x in stride(from:-32.0,through:32.0,by:5.4) {
                index += 1
                let bx=x+sin(Double(index)*2.7)*0.65, bz=z+cos(Double(index)*1.3)*0.55
                let w=2.7+Double(index%3)*0.40, d=2.9+Double(index%4)*0.28
                if abs(bx-24)<3 || abs(bx+24)<3 || abs(bz-25)<3 || abs(bz+25)<3 { continue }
                if abs(bx)<11 && bz < finishZ-2 && bz > finishZ-10 { continue }
                if bx > 17 && bz > 7 && bz < 22 { continue } // spaceport apron
                guard clearLot(bx,bz,w+0.8,d+1.0) else { continue }
                // Low roofscape toward the circuit; a varied outer silhouette.
                let h=2.1+Double(index%5)*0.43
                building(bx,bz,w:w,d:d,h:h,index:index)
            }
        }
        // Individual infield buildings only where the whole footprint fits.
        for (i,pt) in [(0,(-6.0,3.0)),(1,(1.0,10.0)),(2,(8.0,-9.0))] {
            if clearLot(pt.0,pt.1,2.6,2.6) { building(pt.0,pt.1,w:1.8,d:1.9,h:1.65,index:80+i) }
        }
    }

    private func building(_ x:Double,_ z:Double,w:Double,d:Double,h:Double,index:Int,record:Bool=true) {
        buildings += 1
        if record { lots.append(TownLot(x:x,z:z,width:w+0.8,depth:d+1)) }
        let p=paint(x,z), plaster:UInt32=[0xd1b387,0xb99870,0xe2c69d,0xbda080][index%4]
        p.box(0,h/2,0,w,h,d,plaster)
        p.box(0,0.16,0,w+0.22,0.32,d+0.2,trim)
        p.box(0,h-0.08,0,w+0.20,0.20,d+0.2,cream)
        // Low parapets, open roofs and domes produce the desert-port silhouette.
        if index%3 != 1 {
            let r=min(w,d)*0.40
            p.dome(0,h+0.02,0,r,r*0.68,r,plaster)
            p.cylinder(0,h+r*0.68+0.09,0,0.07,0.06,0.18,dark,detail:true)
        } else {
            for sx in [-1.0,1] { p.box(sx*(w/2-0.05),h+0.14,0,0.14,0.3,d,cream) }
            for sz in [-1.0,1] { p.box(0,h+0.14,sz*(d/2-0.05),w,0.3,0.14,cream) }
            p.box(-w*0.2,h+0.36,0,w*0.33,0.7,d*0.33,trim)
            p.cylinder(w*0.24,h+0.28,0,0.32,0.32,0.55,teal,detail:true)
        }
        // Entrances on both facades so the race never sees blank asset backs.
        for side in [-1.0,1] {
            p.box(0,0.74,side*(d/2+0.025),0.82,1.48,0.035,dark)
            p.box(0,1.52,side*(d/2+0.045),1.04,0.18,0.09,trim,detail:true)
            for sx in [-0.51,0.51] { p.box(sx,0.72,side*(d/2+0.05),0.13,1.44,0.12,cream,detail:true) }
            for wx in [-w*0.32,w*0.32] {
                p.box(wx,h*0.64,side*(d/2+0.03),0.38,0.52,0.035,dark,detail:true)
                p.box(wx,h*0.64-0.3,side*(d/2+0.07),0.54,0.10,0.18,cream,detail:true)
            }
            if index%2 == 0 {
                p.box(0,1.83,side*(d/2+0.38),w*0.78,0.055,0.8,index%4 == 0 ? teal : rust)
            }
        }
        // Buttresses, rooftop service pipes and painted bands distinguish kits.
        for sx in [-1.0,1] {
            for sz in [-1.0,1] { p.box(sx*(w/2-0.08),h*0.43,sz*(d/2-0.08),0.30,h*0.86,0.30,cream,detail:true) }
            p.box(sx*(w/2+0.02),h*0.58,0,0.04,0.23,d*0.76,index%3 == 0 ? teal : rust,detail:true)
        }
        p.cylinder(w*0.32,h+0.37,-d*0.25,0.10,0.10,0.75,dark,detail:true)
        if index%4 == 0 {
            p.box(w*0.32,h+1.05,-d*0.25,0.028,1.3,0.028,dark,detail:true)
            p.box(w*0.32,h+1.45,-d*0.25,0.70,0.035,0.035,dark,detail:true)
        }
    }

    private func buildLandmarks() {
        // Spaceport hangar and landing circle, outside the circuit.
        let p=paint(23,14)
        p.box(3,0.035,0,9,0.07,12,0x9f947b)
        p.cylinder(3,0.08,1.0,3.7,3.7,0.06,trim)
        p.cylinder(3,0.115,1.0,3.4,3.4,0.015,0xb7a98d)
        for i in 0..<12 {
            let a=Double(i)*Double.pi/6
            p.box(3+cos(a)*3.55,0.14,1+sin(a)*3.55,0.25,0.04,0.25,cream,detail:true)
        }
        p.box(3,2.3,7.0,9,4.6,4.2,sand)
        p.box(3,1.85,4.87,7.5,3.7,0.055,dark)
        p.box(3,4.8,7,9.4,0.40,4.5,cream)
