            }
        }
        let canopy=InfieldLayout.canopies[0]
        let profile=RobotCollisions.profiles[0]
        for (position,expected) in [(SIMD3<Double>(-8.8,0,-7),false),(SIMD3<Double>(-6,2,-8.8),false),(SIMD3<Double>(-8.8,2,-7),true)] {
